export function addUSBPanel({getSnapshot,send}){
 const anchor=document.getElementById('pico-session-status');if(!anchor)return;
 const section=document.createElement('section');section.id='pico-usb-panel';section.innerHTML='<h3>Sanal USB host</h3><p>İşlemler yalnız simülasyondaki C firmware’ine gider; bilgisayara gerçek klavye/diske bağlanmaz.</p><div data-usb-hid><label>Klavye LED bitleri <input data-usb-led type="number" value="2" min="0" max="31"></label><button data-usb-command="hid-led">SET_REPORT gönder</button></div><div data-usb-msc><label>Blok (LBA) <input data-usb-lba type="number" value="0" min="0" max="65535"></label><button data-usb-command="msc-inquiry">INQUIRY</button> <button data-usb-command="msc-capacity">Kapasite</button> <button data-usb-command="msc-read">512 bayt oku</button> <button data-usb-command="msc-write">Deneme deseni yaz</button></div><div data-usb-dfu><label>Blok <input data-usb-block type="number" min="0" max="65535" value="0"></label><label>İndirilecek metin <input data-usb-text maxlength="128" value="WIREVO-DFU-084"></label><button data-usb-command="dfu-download">DNLOAD</button> <button data-usb-command="dfu-upload">UPLOAD 16B</button> <button data-usb-command="dfu-status">GETSTATUS</button> <button data-usb-command="dfu-manifest">Manifest</button> <button data-usb-command="dfu-abort">ABORT</button> <button data-usb-command="dfu-clear">CLRSTATUS</button></div><pre data-usb-state></pre>';anchor.after(section);
 section.querySelectorAll('[data-usb-command]').forEach(button=>button.onclick=()=>send({type:'pico-usb',action:button.dataset.usbCommand,value:Number(section.querySelector('[data-usb-led]').value),lba:Number(section.querySelector('[data-usb-lba]').value),block:Number(section.querySelector('[data-usb-block]').value),text:section.querySelector('[data-usb-text]').value}));
 updateUSBPanel(getSnapshot());
}
export function updateUSBPanel(snapshot){const section=document.getElementById('pico-usb-panel');if(!section)return;const u=snapshot?.pico?.usb;section.querySelector('[data-usb-hid]').hidden=u?.kind!=='hid';section.querySelector('[data-usb-msc]').hidden=u?.kind!=='msc';section.querySelector('[data-usb-dfu]').hidden=u?.kind!=='dfu';const lines=['Sınıf: '+(u?.kind||'henüz enumerate edilmedi'),'Host: '+(u?.connected?'bağlı':'bekliyor')];if(u?.reports?.length)lines.push('HID raporları: '+u.reports.map(r=>r.map(b=>b.toString(16).padStart(2,'0')).join(' ')).join('\n'));if(u?.msc)lines.push('MSC: '+(u.msc.done?'tamamlandı':'sürüyor')+' · CSW '+u.msc.status+' · residue '+u.msc.residue+' · '+u.msc.bytes+' bayt',u.msc.hex);if(u?.control)lines.push('Kontrol: '+(u.control.done?'tamamlandı':'sürüyor')+' · '+u.control.bytes+' bayt',u.control.hex);section.querySelector('[data-usb-state]').textContent=lines.join('\n');}
